@test("insert and delete")
def _():
    ed = TextEditor("hello")
    ed.insert(5, " world")
    ed.delete(0, 1)
    assert ed.text == "ello world", f"text = {ed.text!r}"

@test("out-of-range edits raise IndexError and change nothing")
def _():
    ed = TextEditor("abc")
    raises(IndexError, ed.insert, 4, "x")
    raises(IndexError, ed.insert, -1, "x")
    raises(IndexError, ed.delete, 2, 5)
    assert ed.text == "abc"

@test("undo reverts edits in reverse order")
def _():
    ed = TextEditor("")
    ed.insert(0, "abc")
    ed.insert(3, "def")
    ed.delete(1, 2)
    assert ed.text == "adef"
    assert ed.undo() and ed.text == "abcdef", f"after 1 undo: {ed.text!r}"
    assert ed.undo() and ed.text == "abc"
    assert ed.undo() and ed.text == ""

@test("redo re-applies undone edits")
def _():
    ed = TextEditor("x")
    ed.insert(1, "yz")
    ed.delete(0, 1)
    ed.undo(); ed.undo()
    assert ed.redo() and ed.text == "xyz"
    assert ed.redo() and ed.text == "yz"

@test("undo/redo return False when there's nothing to do")
def _():
    ed = TextEditor("x")
    assert ed.undo() is False and ed.redo() is False
    assert ed.text == "x"

@test("a new edit clears the redo history")
def _():
    ed = TextEditor("")
    ed.insert(0, "a")
    ed.undo()
    ed.insert(0, "b")
    assert ed.redo() is False and ed.text == "b", f"text = {ed.text!r}"

@test("can_undo and can_redo")
def _():
    ed = TextEditor("")
    assert not ed.can_undo and not ed.can_redo
    ed.insert(0, "a")
    assert ed.can_undo and not ed.can_redo
    ed.undo()
    assert not ed.can_undo and ed.can_redo

@test("failed edits don't enter the history")
def _():
    ed = TextEditor("abc")
    ed.insert(0, ">")
    try:
        ed.delete(10, 1)
    except IndexError:
        pass
    assert ed.undo() and ed.text == "abc"
    assert ed.undo() is False

@test("text is read-only")
def _():
    raises(AttributeError, setattr, TextEditor("a"), "text", "b")

