class _Insert:
    def __init__(self, pos, s):
        self.pos, self.s = pos, s

    def apply(self, text):
        return text[:self.pos] + self.s + text[self.pos:]

    def revert(self, text):
        return text[:self.pos] + text[self.pos + len(self.s):]


class _Delete:
    def __init__(self, pos, removed):
        self.pos, self.removed = pos, removed  # remembers what it deleted, to put it back

    def apply(self, text):
        return text[:self.pos] + text[self.pos + len(self.removed):]

    def revert(self, text):
        return text[:self.pos] + self.removed + text[self.pos:]


class TextEditor:
    def __init__(self, text=""):
        self._text = text
        self._undo = []
        self._redo = []

    @property
    def text(self):
        return self._text

    @property
    def can_undo(self):
        return bool(self._undo)

    @property
    def can_redo(self):
        return bool(self._redo)

    def _do(self, command):
        self._text = command.apply(self._text)
        self._undo.append(command)
        self._redo.clear()  # a new edit invalidates the old "future"

    def insert(self, pos, s):
        if not 0 <= pos <= len(self._text):
            raise IndexError(f"position {pos} is outside the text")
        self._do(_Insert(pos, s))

    def delete(self, pos, n):
        if pos < 0 or n < 0 or pos + n > len(self._text):
            raise IndexError(f"can't delete {n} characters at {pos}")
        self._do(_Delete(pos, self._text[pos:pos + n]))

    def undo(self):
        if not self._undo:
            return False
        command = self._undo.pop()
        self._text = command.revert(self._text)
        self._redo.append(command)
        return True

    def redo(self):
        if not self._redo:
            return False
        command = self._redo.pop()
        self._text = command.apply(self._text)
        self._undo.append(command)
        return True
